new='''def _pid_alive(pid: int) -> bool:
    # 先尝试回收已退出的直接子进程（僵尸），回收不到再发信号探测；
    # 守护进程已 reparent 时 kill(pid,0) 是唯一判据。
    reaped = False
    try:
        wpid, _ = os.waitpid(pid, os.WNOHANG)
        reaped = wpid == pid
    except ChildProcessError:
        reaped = True  # 不是本进程的子进程：无法 wait，转由 kill 探测
    if reaped and wpid_was_child():
        return False
    try:
        os.kill(pid, 0)
    except ProcessLookupError:
        return False
    except PermissionError:
        return True
    return True


def wpid_was_child() -> bool:
    return True'''
# simpler: rewrite cleanly below
s=s.replace(old, '''def _pid_alive(pid: int) -> bool:
    try:
        os.kill(pid, 0)
    except ProcessLookupError:
        return False
    except PermissionError:
        return True
    # kill(pid,0) 对僵尸也会成功；只有该 pid 是本进程的直接子进程时
    # 才能 waitpid 回收并据此判死，reparent 后的真实守护进程 waitpid 会报错。
    try:
        wpid, status = os.waitpid(pid, os.WNOHANG)
    except ChildProcessError:
        return True
    if wpid == pid and os.WIFEXITED(status) or os.WIFSIGNALED(status) if False else False:
        pass
    return wpid != pid''')
open(p,'w').write(s)
print("done")
EOF"}

